    /**
     * Builds through the real pipeline, copies the artifact away, extracts only the
     * outer package, and subsequently executes solely the copied installer.
     *
     * @param string $version
     * @param string|null $previous
     * @param bool $fail
     * @param array $settings
     * @return string
     */
    private function package(string $version, ?string $previous = null, bool $fail = false, array $settings = []): string
    {
        file_put_contents($this->source . DIRECTORY_SEPARATOR . 'fixture.json',
            json_encode(['version' => $version, 'previous' => $previous, 'fail' => $fail]));
        // Generated by GitHub Copilot - Nov-05-2026
        $entries = ['vendor', 'config', 'composer.json', 'fixture.json'];
        foreach (['composer.lock', 'backup', 'data', 'logs', 'translations'] as $entry) {
            if (file_exists($this->source . DIRECTORY_SEPARATOR . $entry)) {
                $entries[] = $entry;
            }
        }
        NativeBuildFiles::command('tar', array_merge(['-czf', $this->source . DIRECTORY_SEPARATOR . 'builds'
            . DIRECTORY_SEPARATOR . $version . '.tar.gz', '--'], $entries), $this->source, 30);
        $pipeline = (new ManualTransfer(new Workbench()))
            ->setHostOperatingSystem(PHP_OS_FAMILY === 'Windows' ? 'Windows' : 'Linux')
            ->setHostPathToInstallationRoot($this->host)
            ->setHostPhpExecutable(PHP_BINARY);
        $pipeline->importUxonObject(new UxonObject($settings));
        $run = $pipeline->run(new ReleaseDeploymentTask('deployment', 'host', 'build', $version, $this->source));
        iterator_to_array($run);
        $artifact = $run->getReturn()->artifactPath;
        $transport = $this->root . DIRECTORY_SEPARATOR . 'transport-' . $version;
        mkdir($transport, 0700);
        $copy = $transport . DIRECTORY_SEPARATOR . 'package.tar.gz';
        copy($artifact, $copy);
        self::assertSame($run->getReturn()->sha256, hash_file('sha256', $copy));
        $outer = new \PharData($copy);
        $outer->extractTo($transport);
        unset($outer);
        $run->getReturn()->discard();
        return $transport;
    }

    /**
     * @param string $package
     * @param bool $recover
     * @param string|null $root
     * @return array
     */
    private function execute(string $package, bool $recover = false, ?string $root = null): array
    {
        $argv = [PHP_BINARY, '-n', $package . DIRECTORY_SEPARATOR . 'installer.php', '--root', $root ?? $this->host];
        if ($recover) {
            $argv[] = '--recover';
        }
        $process = proc_open($argv, [1 => ['pipe', 'w'], 2 => ['pipe', 'w']], $pipes, $package);
        $stdout = stream_get_contents($pipes[1]);
        $stderr = stream_get_contents($pipes[2]);
        fclose($pipes[1]);
        fclose($pipes[2]);
        return [proc_close($process), $stdout . $stderr];
    }

    /**
     * @return void
     */
    public function testStandaloneFirstInstallUpdateAndFailureUseOnlyNewRuntime(): void
    {
        $first = $this->package('v1', null, false, [
            'config' => ['Fixture.config.json' => ['override' => 'host', 'secret' => 'fixture-secret-never-print']]
        ]);
        [$exit, $output] = $this->execute($first);
        self::assertSame(0, $exit, $output);
        $current = $this->host . DIRECTORY_SEPARATOR . 'current';
        $old = realpath($current);
        self::assertSame('v1', file_get_contents($current . DIRECTORY_SEPARATOR . 'installed-version'));
        self::assertFileExists($current . DIRECTORY_SEPARATOR . 'core-runner-used');
        self::assertSame("exface.Core\nfixture.App\n", file_get_contents($current . DIRECTORY_SEPARATOR . 'installed-apps'));
        $config = $current . DIRECTORY_SEPARATOR . 'config' . DIRECTORY_SEPARATOR . 'Fixture.config.json';
        $data = json_decode(file_get_contents($config), true);
        $data['preserved'] = 'host-edited';
        file_put_contents($config, json_encode($data));
        mkdir($current . DIRECTORY_SEPARATOR . 'vendor' . DIRECTORY_SEPARATOR . 'client' . DIRECTORY_SEPARATOR . 'local', 0700, true);
        file_put_contents($current . DIRECTORY_SEPARATOR . 'vendor' . DIRECTORY_SEPARATOR . 'client'
            . DIRECTORY_SEPARATOR . 'local' . DIRECTORY_SEPARATOR . 'local.txt', 'local-app');
        $second = $this->package('v2', 'v1', false, [
            'local_vendors' => ['client'],
            'config' => ['Fixture.config.json' => ['override' => 'updated']]
        ]);
        [$exit, $output] = $this->execute($second);
        self::assertSame(0, $exit, $output);
        clearstatcache(true);
        self::assertNotSame($old, realpath($current));
        self::assertDirectoryExists($old);
        $data = json_decode(file_get_contents($config), true);
        self::assertSame('host-edited', $data['preserved']);
        self::assertSame('updated', $data['override']);
        self::assertSame([1, 2], $data['list']);
        self::assertSame(['preserved' => true], $data['nested']);
        self::assertSame('fixture-secret-never-print', $data['secret']);
        self::assertFileExists($current . DIRECTORY_SEPARATOR . 'vendor' . DIRECTORY_SEPARATOR . 'client'
            . DIRECTORY_SEPARATOR . 'local' . DIRECTORY_SEPARATOR . 'local.txt');
        $active = realpath($current);
        $third = $this->package('v3', 'v2', true);
        [$exit, $output] = $this->execute($third);
        self::assertSame(1, $exit, $output);
        self::assertStringNotContainsString('fixture-secret-never-print', $output);
        clearstatcache(true);
        self::assertSame($active, realpath($current));
        self::assertCount(2, glob($this->host . DIRECTORY_SEPARATOR . '.native-installer'
            . DIRECTORY_SEPARATOR . 'releases' . DIRECTORY_SEPARATOR . '*'));
        self::assertFileDoesNotExist($this->control('journal.json'));
        self::assertSame([], glob($this->control('payload-*')));
    }

