    /**
     * @return void
     */
    public function testRootIntegrityUnsupportedSettingsAndConcurrentLockFailClosed(): void
    {
        $package = $this->package('v1');
        [$exit, $output] = $this->execute($package, false, 'relative-root');
        self::assertSame(1, $exit);
        self::assertStringContainsString('absolute', $output);
        $other = $this->root . DIRECTORY_SEPARATOR . 'other';
        mkdir($other);
        [$exit, $output] = $this->execute($package, false, $other);
        self::assertSame(1, $exit);
        self::assertStringContainsString('authoritative', $output);
        file_put_contents($package . DIRECTORY_SEPARATOR . 'build.tar.gz', 'tampered');
        [$exit, $output] = $this->execute($package);
        self::assertSame(1, $exit);
        self::assertStringContainsString('integrity', $output);
        $lock = fopen($this->control('install.lock'), 'c+b');
        flock($lock, LOCK_EX);
        try {
            [$exit, $output] = $this->execute($package);
            self::assertSame(1, $exit);
            self::assertStringContainsString('lock', $output);
        } finally {
            fclose($lock);
        }
        foreach ([
            ['shared_dirs' => ['config']], ['local_packages' => ['../local']],
            ['keep_releases' => 1], ['copy_dirs' => ['nested/path']]
        ] as $index => $settings) {
            $unsupported = $this->package('unsupported' . $index);
            $manifestPath = $unsupported . DIRECTORY_SEPARATOR . 'manifest.json';
            $manifest = json_decode(file_get_contents($manifestPath), true, 512, JSON_THROW_ON_ERROR);
            $manifest['pipeline'] = array_replace($manifest['pipeline'], $settings);
            file_put_contents($manifestPath, json_encode($manifest, JSON_THROW_ON_ERROR));
            [$exit, $output] = $this->execute($unsupported);
            self::assertSame(1, $exit, $output);
        }
        self::assertDirectoryDoesNotExist($this->host . DIRECTORY_SEPARATOR . 'current');
        self::assertFileDoesNotExist($this->control('journal.json'));
    }

    /**
