    public function testInterruptedActivationRecoveryAndWorkerLock(): void
    {
        $package = $this->package('v1');
        [$exit, $output] = $this->execute($package);
        self::assertSame(0, $exit, $output);
        $current = $this->host . DIRECTORY_SEPARATOR . 'current';
        $previous = realpath($current);
        $id = str_repeat('a', 32);
        $release = $this->control('releases') . DIRECTORY_SEPARATOR . $id;
        mkdir($release);
        file_put_contents($release . DIRECTORY_SEPARATOR . 'interrupted', 'fixture');
        rename($current, $this->control('previous'));
        if (PHP_OS_FAMILY === 'Windows') {
            NativeBuildFiles::command('powershell.exe', ['-NoProfile', '-NonInteractive', '-Command',
                'New-Item -ItemType Junction -Path $env:FIXTURE_LINK -Target $env:FIXTURE_TARGET | Out-Null'],
                $this->host, 30, ['FIXTURE_LINK' => $current, 'FIXTURE_TARGET' => $release]);
        } else {
            symlink($release, $current);
        }
        file_put_contents($this->control('journal.json'), json_encode(['id' => $id, 'previous' => $previous, 'committed' => false]));
        [$exit, $output] = $this->execute($package);
        self::assertSame(1, $exit);
        self::assertStringContainsString('Interrupted', $output);
        $worker = fopen($this->control('runtime.lock'), 'c+b');
        flock($worker, LOCK_SH);
        try {
            [$exit, $output] = $this->execute($package, true);
            self::assertSame(1, $exit);
            self::assertStringContainsString('worker', $output);
        } finally {
            fclose($worker);
        }
        [$exit, $output] = $this->execute($package, true);
        self::assertSame(0, $exit, $output);
        clearstatcache(true);
        self::assertSame($previous, realpath($current));
        self::assertDirectoryDoesNotExist($release);
        self::assertFileDoesNotExist($this->control('journal.json'));
        [$exit, $output] = $this->execute($package, true);
        self::assertSame(0, $exit, $output);
    }

