    /**
     * Mutates the transferred package with a matching payload hash, exercising the
     * independent host archive parser rather than only producer-side inspection.
     *
     * @param string $name
     * @param string $type
     * @return void
     */
    #[DataProvider('maliciousEntries')]
    public function testStandaloneRejectsMaliciousArchive(string $name, string $type): void
    {
        $package = $this->package('v1');
        $header = str_pad($name, 100, "\0")
            . sprintf("%07o\0%07o\0%07o\0%011o\0%011o\0", 0644, 0, 0, 0, 0)
            . '        ' . $type . str_repeat("\0", 100) . "ustar\0" . '00' . str_repeat("\0", 247);
        $header = substr_replace($header, sprintf("%06o\0 ", array_sum(unpack('C*', $header))), 148, 8);
        file_put_contents($package . DIRECTORY_SEPARATOR . 'build.tar.gz', gzencode($header . str_repeat("\0", 1024)));
        $manifestPath = $package . DIRECTORY_SEPARATOR . 'manifest.json';
        $manifest = json_decode(file_get_contents($manifestPath), true);
        $manifest['payload']['sha256'] = hash_file('sha256', $package . DIRECTORY_SEPARATOR . 'build.tar.gz');
        file_put_contents($manifestPath, json_encode($manifest));
        [$exit, $output] = $this->execute($package);
        self::assertSame(1, $exit, $output);
        self::assertStringContainsString('archive', $output);
        self::assertDirectoryDoesNotExist($this->host . DIRECTORY_SEPARATOR . 'current');
        self::assertFileDoesNotExist($this->root . DIRECTORY_SEPARATOR . 'outside');
        self::assertFileDoesNotExist($this->control('journal.json'));
        self::assertSame([], glob($this->control('payload-*')));
    }
